def isBalanced(root):
    # Helper function returns height if balanced, else -1
    def check(node):
        # Base case: empty node has height 0
        if not node:
            return 0
        # Get height of left subtree
        left_h = check(node.left)
        # If left subtree is unbalanced, propagate -1 upwards
        if left_h == -1:
            return -1
        # Get height of right subtree
        right_h = check(node.right)
        # If right subtree is unbalanced, propagate -1 upwards
        if right_h == -1:
            return -1
        # If heights differ by more than 1, current subtree is unbalanced
        if abs(left_h - right_h) > 1:
            return -1
        # Return actual height of current node
        return 1 + max(left_h, right_h)

    # Root is balanced if check does not return -1
    return check(root) != -1

def diameterOfBinaryTree(root):
    # Helper to compute height of a subtree
    def height(node):
        if not node:
            return 0
        return 1 + max(height(node.left), height(node.right))

    # Base case: empty node has diameter 0
    if not root:
        return 0
    # Calculate left and right heights
    left_h = height(root.left)
    right_h = height(root.right)
    # Diameter through current root
    curr_diameter = left_h + right_h
    # Recurse on left and right subtrees
    left_diameter = diameterOfBinaryTree(root.left)
    right_diameter = diameterOfBinaryTree(root.right)
    # Return maximum of all diameters
    return max(curr_diameter, left_diameter, right_diameter)

def maxPathSum(root):
    # Helper to compute max branch sum from a node
    def max_branch(node):
        if not node:
            return 0
        # Return maximum branch sum (must be non-negative)
        return max(0, node.val + max(max_branch(node.left), max_branch(node.right)))

    # Base case
    if not root:
        return float('-inf')
    # Calculate max path sum passing through root
    left_contrib = max(0, max_branch(root.left))
    right_contrib = max(0, max_branch(root.right))
    curr_sum = root.val + left_contrib + right_contrib
    # Recurse on children
    left_max = maxPathSum(root.left)
    right_max = maxPathSum(root.right)
    # Return maximum of all
    return max(curr_sum, left_max, right_max)

def isSameTree(p, q):
    # If both nodes are null, trees are identical from here
    if not p and not q:
        return True
    # If one node is null and the other is not, they are not identical
    if not p or not q:
        return False
    # If values of current nodes do not match, they are not identical
    if p.val != q.val:
        return False
    # Recursively check left subtrees and right subtrees
    return isSameTree(p.left, q.left) and isSameTree(p.right, q.right)

def zigzagLevelOrder(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        level_nodes = []
        for _ in range(level_size):
            curr = queue.pop(0)
            level_nodes.append(curr.val)
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
        result.append(level_nodes)
    # Reverse odd indexed levels
    for i in range(len(result)):
        if i % 2 == 1:
            result[i].reverse()
    return result

def boundaryTraversal(root):
    if not root:
        return []

    # Check if node is leaf
    def isLeaf(node):
        return not node.left and not node.right

    # Collect left boundary
    def getLeftBoundary(node, res):
        curr = node
        while curr:
            if not isLeaf(curr):
                res.append(curr.val)
            curr = curr.left if curr.left else curr.right

    # Collect leaf nodes
    def getLeaves(node, res):
        if not node:
            return
        if isLeaf(node):
            res.append(node.val)
            return
        getLeaves(node.left, res)
        getLeaves(node.right, res)

    # Collect right boundary (to be reversed)
    def getRightBoundary(node, res):
        curr = node
        temp = []
        while curr:
            if not isLeaf(curr):
                temp.append(curr.val)
            curr = curr.right if curr.right else curr.left
        res.extend(reversed(temp))

    res = []
    if not isLeaf(root):
        res.append(root.val)
    getLeftBoundary(root.left, res)
    getLeaves(root, res)
    getRightBoundary(root.right, res)
    return res

def topView(root):
    col_map = {}
    # DFS traversal
    def dfs(node, row, col):
        if not node:
            return
        # If col not seen, or seen but at a lower depth (row)
        if col not in col_map or row < col_map[col][0]:
            col_map[col] = (row, node.val)
        dfs(node.left, row + 1, col - 1)
        dfs(node.right, row + 1, col + 1)

    dfs(root, 0, 0)
    # Sort columns and extract values
    return [col_map[c][1] for c in sorted(col_map.keys())]

def bottomView(root):
    col_map = {}
    # DFS traversal
    def dfs(node, row, col):
        if not node:
            return
        # Store or overwrite if row is greater or equal
        if col not in col_map or row >= col_map[col][0]:
            col_map[col] = (row, node.val)
        dfs(node.left, row + 1, col - 1)
        dfs(node.right, row + 1, col + 1)

    dfs(root, 0, 0)
    return [col_map[c][1] for c in sorted(col_map.keys())]

def rightSideView(root):
    if not root:
        return []
    queue = [root]
    result = []
    while queue:
        level_size = len(queue)
        for i in range(level_size):
            curr = queue.pop(0)
            # If it is the last element of the level, add to result
            if i == level_size - 1:
                result.append(curr.val)
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
    return result

