def isSymmetric(root):
    # Helper function to check if two subtrees are mirrors of each other
    def isMirror(t1, t2):
        # If both subtrees are null, they are symmetric
        if not t1 and not t2:
            return True
        # If only one is null, they are not symmetric
        if not t1 or not t2:
            return False
        # Check if current values match and their subtrees are mirrored
        return (t1.val == t2.val and 
                isMirror(t1.left, t2.right) and 
                isMirror(t1.right, t2.left))

    # If root is null, it is symmetric
    if not root:
        return True
    # Check if left and right subtrees are mirrors of each other
    return isMirror(root.left, root.right)

def solve(root, target):
    all_paths = []
    # DFS to find all paths
    def dfs(node, path):
        if not node:
            return
        curr_path = path + [node.val]
        all_paths.append(curr_path)
        dfs(node.left, curr_path)
        dfs(node.right, curr_path)

    dfs(root, [])
    # Search for path ending with target
    for p in all_paths:
        if p[-1] == target:
            return p
    return []

def lowestCommonAncestor(root, p, q):
    # Find paths for p and q
    def get_path(node, target, path):
        if not node:
            return False
        path.append(node)
        if node == target:
            return True
        if get_path(node.left, target, path) or get_path(node.right, target, path):
            return True
        path.pop()
        return False

    path_p, path_q = [], []
    get_path(root, p, path_p)
    get_path(root, q, path_q)

    # Compare paths to find LCA
    lca = None
    for node_p, node_q in zip(path_p, path_q):
        if node_p == node_q:
            lca = node_p
        else:
            break
    return lca
